const AppointmentTemplateSchema = z
  .object({
    archived: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Indicats that the object has been soft-deleted and should not be used',
        readOnly: true,
        title: 'Archived',
      }),
    date_end: z.string().exactOptional().openapi({ description: '', title: 'Date end' }),
    date_start: z.string().exactOptional().openapi({ description: '', title: 'Date start' }),
    duration: z
      .int()
      .exactOptional()
      .openapi({ description: 'Length of an appointment in minutes', title: 'Duration' }),
    exam_room: z
      .int()
      .openapi({ description: '**1-based** index for the exam room', title: 'Exam room' }),
    id: z.int().exactOptional().openapi({ description: '', readOnly: true, title: 'ID' }),
    office: z.int().openapi({ description: '', title: 'Office' }),
    open_slots: z
      .array(
        z
          .object({
            end: z.string().exactOptional().openapi({ description: '', title: 'End' }),
            start: z.string().exactOptional().openapi({ description: '', title: 'Start' }),
          })
          .openapi({ description: '', title: 'Open Slot', required: [] }),
      )
      .exactOptional()
      .openapi({
        description:
          'Array of time intervals during which the template is available. Only computed if the available and verbose query parameters are passed. Note that only slots long enough to fit an appointment with the corresponding profile are included.',
        title: 'Open Slots',
      }),
    profile: z
      .int()
      .openapi({ description: 'ID of the appointment profile to default to', title: 'Profile' }),
    scheduled_time: z.string().openapi({ description: '', title: 'Scheduled time' }),
    week_days: z
      .array(z.int().openapi({ description: '', title: '' }))
      .openapi({
        description: 'Array of integers that indicate week days (`0` = Monday, ..., `6` = Sunday)',
        title: 'Week days',
      }),
  })
  .openapi({
    description:
      'Appointment templates are blocks of time during which a doctor usually sees appointments with the same profile. These may have a longer duration then the corresponding profile, in which case they may allow multiple appointments to be booked during that period.',
    required: ['office', 'exam_room', 'scheduled_time', 'profile', 'week_days'],
    'x-verbose-required': ['open_slots'],
  })
  .openapi('AppointmentTemplate')

